sp_widget.client_script:
function($rootScope, $scope) {
	/* widget controller */
	const c = this;

	// Respond to a note being selected by asking for data from the server
	$rootScope.$on('selectNote', (event,data) => {
		c.server.get({
			action: 'getNote',
			noteID: data
		}).then((r) => {
			c.data.title = r.data.note.title;
			c.data.note = r.data.note.note;
			c.data.noteID = r.data.note.sys_id;
		});
	});

	// Emits an event with the changed note attached
	// Sends changed note to the server to update as well
	c.updateNote = (updateType) => {
		const newNote = {
			"sys_id": c.data.noteID,
			"title": c.data.title,
			"body": c.data.note
		};

		$rootScope.$emit("editedNote", newNote);

    c.server.get({
      action: 'updateNote',
      newNote: newNote
    });
  }
}

sp_widget.script:
(function() {
	if (input) {
		var note = new GlideRecord('x_snc_createnotes_note');

		// Note List Click handler
		if (input.action == 'getNote' && note.get(input.noteID)) {
			data.note = {};
			$sp.getRecordValues(data.note, note, "title, note, sys_id");
		}

		// Update a note in the db after it was changed on the widget
		else if (input.action == 'updateNote' && note.get(input.newNote.sys_id)) { 
			note.title = input.newNote.title; 
			note.note = input.newNote.body; 
			note.update(); 
		}
	}
})();
